mapper.select:
select DATE_FORMAT(info.EFF_DATE,'%Y-%m-%d') as effDate, info.INT_TYPE as intType, info.RATE*100 as rate, info.BASIS as basis, info.FINPROD_ID as accountId, bok.ACCT_TYPE as accountType, info.CASH_ID as cashId, info.INT_TYPE as intRateStructure, info.BENCHMARK_ID as basicRate
from FIN_RATE_INFO info left join BOK_BOOKSET_CAPACCT_INFO bok on info.FINPROD_ID =bok.ACCT_NO where 1=1
and info.CASH_ID=#{cashId}
and info.EFF_DATE =STR_TO_DATE(#{effDate},'%Y-%m-%d')
and bok.BOOKSET_ID = #{booksetId}
and bok.CCY = #{ccy}
